mapper.select:
SELECT  FROM `${tableName}`
WHERE `code` = #{code}
AND `adjustflag` = #{adjustFlag}
ORDER BY `trade_date` DESC LIMIT 1

SELECT `code`, `adjustflag` AS `adjustFlag`, MIN(`trade_date`) AS `firstDate`, MAX(`trade_date`) AS `latestDate` FROM `stock_daily_all` WHERE `adjustflag` IN
#{flag}
AND `code` IN
#{code}
GROUP BY `code`, `adjustflag`
